#include "opensim/framework/agent_position.hpp"
#include "opensim/network/osd_json.hpp"
#include <bit>
#include <iomanip>
#include <iostream>
#include <sstream>
using namespace opensim;using network::Value;
std::string hex(std::string_view s){std::string out;const char* h="0123456789abcdef";for(unsigned char c:s){out+=h[c>>4];out+=h[c&15];}return out;}
std::string decode(const std::string& s){std::string out;for(std::size_t i=0;i<s.size();i+=2)out+=static_cast<char>(std::stoi(s.substr(i,2),nullptr,16));return out;}
framework::Uuid id(int n){return framework::Uuid("00000000-0000-0000-0000-00000000000"+std::to_string(n));}
std::string bits(float n){std::ostringstream s;s<<std::hex<<std::setw(8)<<std::setfill('0')<<std::bit_cast<std::uint32_t>(n);return s.str();}
std::string binary(const network::BinaryData& data){if(!data)return "-";return hex(std::string(reinterpret_cast<const char*>(data->data()),data->size()));}
std::string state(const framework::AgentPosition& p){std::string out=p.agent_id.str()+"|"+p.session_id.str()+"|"+std::to_string(p.region_handle)+"|"+std::to_string(p.circuit_code)+"|"+bits(p.far);for(auto v:{p.position,p.velocity,p.center,p.size,p.at_axis,p.left_axis,p.up_axis})out+="|"+bits(v.x)+","+bits(v.y)+","+bits(v.z);out+="|"+std::to_string(p.changed_grid)+"|"+(p.god_data?hex(network::osd_json(*p.god_data,true)):"-")+"|"+binary(p.throttles)+"|";if(!p.children_cap_seeds)out+="-";else for(auto& [h,s]:*p.children_cap_seeds)out+=std::to_string(h)+":"+(s?hex(*s):"-")+";";return out;}
int main(){std::string line;while(std::getline(std::cin,line)){std::istringstream in(line);int profile;std::string data;in>>profile>>data;auto args=network::parse_osd_json(decode(data));framework::AgentPosition p;if(profile&1){p.agent_id=id(7);p.session_id=id(8);p.region_handle=~std::uint64_t{};p.circuit_code=~std::uint32_t{};p.far=123.5f;p.position={1,2,3};p.velocity={4,5,6};p.center={7,8,9};p.size={10,11,12};p.at_axis={13,14,15};p.left_axis={16,17,18};p.up_axis={19,20,21};p.changed_grid=true;p.god_data=std::make_shared<Value>(Value::object({}));p.god_data->set("ViewerUiIsGod",Value(false));p.throttles=std::make_shared<std::vector<std::uint8_t>>(std::initializer_list<std::uint8_t>{1,2,3});p.children_cap_seeds=std::make_shared<framework::AgentPosition::ChildrenSeeds>();(*p.children_cap_seeds)[9]="nine";(*p.children_cap_seeds)[8]="eight";(*p.children_cap_seeds)[7]=std::nullopt;p.children_cap_seeds->erase(8);(*p.children_cap_seeds)[6]="six";}
 bool unpack_failed=false,pack_failed=false;std::string packed;try{if((profile&8)&&args.contains("throttles"))args.set("throttles",network::osd_from_binary(network::osd_binary(args.get("throttles"))));p.unpack(args);if(profile&2){if(args.contains("god_data")&&args.get("god_data").view().kind==Value::Kind::Map){auto& god=args.map.at("god_data");god.set("ViewerUiIsGod",Value(true));god.set("after","source");if(network::osd_boolean(args.get("replace_god")))args.set("god_data",Value::object({}));}if((profile&8)&&args.contains("throttles")){auto bytes=network::osd_binary(args.get("throttles"));if(!bytes->empty())(*bytes)[0]=99;}}if(profile&16){framework::ChildAgentDataUpdate child;child.agent_id=id(5);child.avatar_height=1.75f;child.camera_position={31,32,33};child.draw_distance=64.25f;child.position={41,42,43};child.region_handle=123456789;child.throttles=std::make_shared<std::vector<std::uint8_t>>(std::initializer_list<std::uint8_t>{8,9});child.velocity={51,52,53};p.copy_from(profile&32?nullptr:&child,id(6));(*child.throttles)[0]=77;}}catch(const std::exception&){unpack_failed=true;}
 try{auto value=p.pack();if((profile&4)&&p.god_data&&p.god_data->view().kind==Value::Kind::Map){p.god_data->set("ViewerUiIsGod",Value(false));p.god_data->set("after_pack","shared");}if((profile&4)&&p.throttles&&!p.throttles->empty())(*p.throttles)[0]=55;packed=network::osd_json(value,true);}catch(const std::exception&){pack_failed=true;}
 std::cout<<unpack_failed<<"|"<<pack_failed<<"|"<<hex(packed)<<"|"<<hex(state(p))<<"\n";}}
